<body>
<main class="game">
  <header>
    <div>
      <h1>Rooftop Courier Switchbacks</h1>
      <div class="sub">Toggle switch tiles before the runner reaches them.</div>
    </div>
    <div class="stats">
      <div class="pill"><span>Time</span><strong id="time">60</strong></div>
      <div class="pill"><span>Score</span><strong id="score">0</strong></div>
      <div class="pill"><span>Best</span><strong id="best">0</strong></div>
    </div>
  </header>

  <section class="wrap">
    <div class="boardShell" id="shell">
      <div class="board" id="board"></div>
      <div class="runner hidden" id="runner"></div>
      <div class="overlay" id="overlay">
        <div class="card">
          <h2 id="overlayTitle">Route the rooftop rush</h2>
          <p id="overlayText">Switches decide which walkway the courier takes. Deliver 5 packages before the storm timer hits zero.</p>
          <button class="action" id="startBtn">Start Run</button>
        </div>
      </div>
    </div>

    <aside>
      <div class="panelTitle">Delivery board</div>
      <div class="routeBox" id="jobs"></div>
      <div class="controls">
        <button class="action" id="startSide">Start / Restart</button>
        <button class="action secondary" id="pauseBtn">Pause</button>
      </div>
      <div class="hint">
        Tap yellow-numbered switch tiles. Keyboard: 1 to 6 toggles switches, Space pauses, Enter starts.
      </div>
    </aside>
  </section>
</main>

<script>
(() => {
  const boardEl = document.getElementById("board");
  const shell = document.getElementById("shell");
  const runnerEl = document.getElementById("runner");
  const timeEl = document.getElementById("time");
  const scoreEl = document.getElementById("score");
  const bestEl = document.getElementById("best");
  const jobsEl = document.getElementById("jobs");
  const overlay = document.getElementById("overlay");
  const overlayTitle = document.getElementById("overlayTitle");
  const overlayText = document.getElementById("overlayText");
  const startBtn = document.getElementById("startBtn");
  const startSide = document.getElementById("startSide");
  const pauseBtn = document.getElementById("pauseBtn");

  const W = 7;
  const bestKey = "rooftopCourierSwitchbacksBest";
  let best = Number(localStorage.getItem(bestKey) || 0);
  bestEl.textContent = best;

  const tiles = [
    "empty","empty","depot","empty","empty","empty","empty",
    "empty","empty","ns","empty","goal","ew","goal",
    "goal","ew","sw","ew","switch","ew","goal",
    "empty","empty","ns","empty","ns","empty","empty",
    "empty","empty","switch","ew","switch","ew","goal",
    "empty","empty","ns","empty","ns","empty","empty",
    "empty","goal","nw","ew","switch","ew","goal"
  ];

  const switchIds = [18,30,32,46];
  const switchStates = {
    18: ["sw", "se"],
    30: ["ns", "ne"],
    32: ["ns", "se"],
    46: ["nw", "ne"]
  };
  let state = {18:0,30:0,32:0,46:0};

  const jobsBase = [
    { name: "Water tower drop", goal: 14 },
    { name: "Greenhouse meds", goal: 20 },
    { name: "Radio mast tools", goal: 34 },
    { name: "Night market parcel", goal: 43 },
    { name: "Lantern roof finale", goal: 48 }
  ];

  let jobs = [];
  let currentJob = 0;
  let runner = null;
  let timer = 60;
  let score = 0;
  let running = false;
  let paused = false;
  let lastTick = 0;
  let moveAcc = 0;
  let stormAcc = 0;

  function drawBoard() {
    boardEl.innerHTML = "";
    tiles.forEach((type, i) => {
      const b = document.createElement("button");
      b.className = "tile";
      b.disabled = true;
      b.dataset.i = i;

      if (type === "empty") b.classList.add("empty");
      else if (type === "depot") {
        b.classList.add("depot");
        b.textContent = "🏠";
      } else if (type === "goal") {
        b.classList.add("goal");
        b.textContent = "📍";
      } else if (type === "switch") {
        b.disabled = false;
        b.classList.add("switch", switchStates[i][state[i]]);
        const badge = document.createElement("span");
        badge.className = "badge";
        badge.textContent = switchIds.indexOf(i) + 1;
        b.appendChild(badge);
        b.addEventListener("click", () => toggleSwitch(i));
      } else {
        b.classList.add("roof", "path", type);
      }
      boardEl.appendChild(b);
    });
  }

  function shuffle(arr) {
    return arr.map(v => [Math.random(), v]).sort((a,b) => a[0]-b[0]).map(x => x[1]);
  }

  function startGame() {
    jobs = shuffle([...jobsBase]);
    currentJob = 0;
    timer = 60;
    score = 0;
    running = true;
    paused = false;
    state = {18:0,30:0,32:0,46:0};
    runner = { pos: 2, from: null };
    lastTick = performance.now();
    moveAcc = 0;
    stormAcc = 0;
    runnerEl.classList.remove("hidden");
    overlay.classList.add("hidden");
    pauseBtn.textContent = "Pause";
    updateUI();
    drawBoard();
    placeRunner();
    requestAnimationFrame(loop);
  }

  function endGame(win) {
    running = false;
    runnerEl.classList.add("hidden");
    const bonus = Math.max(0, Math.ceil(timer)) * 4;
    if (win) score += bonus;
    if (score > best) {
      best = score;
      localStorage.setItem(bestKey, best);
    }
    bestEl.textContent = best;
    overlay.classList.remove("hidden");
    overlayTitle.textContent = win ? "Deliveries complete 🏙️" : "Storm won the roof";
    overlayText.textContent = win
      ? `Final score ${score}. Time bonus ${bonus}. Best score ${best}.`
      : `You delivered ${currentJob} of 5 packages. Final score ${score}. Best score ${best}.`;
    startBtn.textContent = "Play Again";
    updateUI();
  }

  function toggleSwitch(i) {
    if (!running || paused) return;
    state[i] = state[i] ? 0 : 1;
    drawBoard();
    const tile = boardEl.querySelector(`[data-i="${i}"]`);
    tile.classList.add("pulse");
    setTimeout(() => tile.classList.remove("pulse"), 240);
  }

  function exitsFor(i) {
    const type = switchIds.includes(i) ? switchStates[i][state[i]] : tiles[i];
    return {
      ns: ["N","S"], ew: ["E","W"],
      ne: ["N","E"], se: ["S","E"], sw: ["S","W"], nw: ["N","W"],
      depot: ["S"], goal: ["N","E","S","W"]
    }[type] || [];
  }

  function neighbor(i, dir) {
    const r = Math.floor(i / W), c = i % W;
    if (dir === "N" && r > 0) return i - W;
    if (dir === "S" && r < W - 1) return i + W;
    if (dir === "E" && c < W - 1) return i + 1;
    if (dir === "W" && c > 0) return i - 1;
    return null;
  }

  function opposite(d) {
    return {N:"S", S:"N", E:"W", W:"E"}[d];
  }

  function stepRunner() {
    if (!runner) return;
    if (runner.pos === jobs[currentJob].goal) {
      score += 100 + Math.ceil(timer);
      currentJob++;
      if (currentJob >= jobs.length) return endGame(true);
      runner.pos = 2;
      runner.from = null;
      updateUI();
      placeRunner();
      return;
    }

    const exits = exitsFor(runner.pos);
    let options = exits
      .map(d => ({ dir: d, to: neighbor(runner.pos, d) }))
      .filter(x => x.to !== null && x.to !== runner.from)
      .filter(x => exitsFor(x.to).includes(opposite(x.dir)));

    if (!options.length && runner.from !== null) {
      options = [{ to: runner.from }];
    }

    if (!options.length) {
      score = Math.max(0, score - 20);
      runner.pos = 2;
      runner.from = null;
    } else {
      const next = options[0].to;
      runner.from = runner.pos;
      runner.pos = next;
    }
    placeRunner();
    updateUI();
  }

  function placeRunner() {
    const rect = shell.getBoundingClientRect();
    const bRect = boardEl.getBoundingClientRect();
    const size = bRect.width / W;
    const r = Math.floor(runner.pos / W);
    const c = runner.pos % W;
    runnerEl.style.left = ((bRect.left - rect.left) + c * size + size / 2) + "px";
    runnerEl.style.top = ((bRect.top - rect.top) + r * size + size / 2) + "px";
  }

  function updateUI() {
    timeEl.textContent = Math.max(0, Math.ceil(timer));
    scoreEl.textContent = score;
    jobsEl.innerHTML = jobs.map((j, idx) => `
      <div class="job ${idx < currentJob ? "done" : ""}">
        ${idx === currentJob ? "➡️ " : idx < currentJob ? "✅ " : "⬜ "}
        ${j.name}
      </div>
    `).join("");
  }

  function loop(now) {
    if (!running) return;
    const dt = Math.min(.05, (now - lastTick) / 1000);
    lastTick = now;

    if (!paused) {
      timer -= dt;
      moveAcc += dt;
      stormAcc += dt;

      const moveSpeed = Math.max(.33, .72 - currentJob * .055);
      if (moveAcc >= moveSpeed) {
        moveAcc = 0;
        stepRunner();
      }
      if (stormAcc >= .25) {
        stormAcc = 0;
        updateUI();
      }
      if (timer <= 0) endGame(false);
    }
    requestAnimationFrame(loop);
  }

  function togglePause() {
    if (!running) return;
    paused = !paused;
    pauseBtn.textContent = paused ? "Resume" : "Pause";
    if (!paused) lastTick = performance.now();
  }

  startBtn.addEventListener("click", startGame);
  startSide.addEventListener("click", startGame);
  pauseBtn.addEventListener("click", togglePause);

  window.addEventListener("resize", () => runner && placeRunner());

  window.addEventListener("keydown", e => {
    if (e.key === "Enter") startGame();
    if (e.code === "Space") {
      e.preventDefault();
      togglePause();
    }
    const n = Number(e.key);
    if (n >= 1 && n <= switchIds.length) toggleSwitch(switchIds[n - 1]);
  });

  jobs = [...jobsBase];
  drawBoard();
  updateUI();
})();
</script>
</body>
</html>
